\begin{abstract}
We give a complete convex-geometric and group-theoretic analysis of the reinforcement-learning-from-preferences objective with a pretraining mix-in,
\[
J_\gamma(q) \;=\; \E_q[r] \;-\; \beta\,\KL(q\|p) \;+\; \gamma\,\E_{d}[\log q],
\]
over strictly positive probability distributions $q$ on a finite response space $\Omega$, where $r$ is a reward model, $p$ a strictly positive reference policy, $d$ a pretraining distribution, and $\beta,\gamma>0$. Four groups of results are established. (i) \emph{Torsor structure}: for $\gamma=0$ the additive group of reward models modulo constants acts simply transitively on strictly positive policies by exponential tilting, and in the mean-zero gauge this action is a homeomorphism onto the interior of the simplex, with inverse the implicit reward $\beta\log(q/p)$. (ii) \emph{Legendre duality}: the alignment value $F(r)=\beta\log\sum_y p(y)e^{r(y)/\beta}$ and the KL penalty form an exact convex-conjugate pair with attained maximizers on both sides; the Bregman divergence of $F$ equals $\beta$ times the KL divergence between induced policies, and Fenchel--Young holds with equality precisely on the graph of the tilting map. (iii) \emph{Sharp reward-hacking budgets}: $F$ is $1$-Lipschitz for the sup-norm, the constant $1$ is optimal, and the sup-norm cannot be replaced by any reference-weighted quadratic norm. (iv) \emph{The mix-in}: the optimum exists and is unique, is characterized by constancy of a coordinatewise score, equivalently by the self-consistent Gibbs equation $q=\pi_{r+\gamma d/q}$, and satisfies an explicit anti-starvation floor, a Pythagorean drift bound, monotone comparative statics in $\gamma$, and a two-sided KL stability band $\beta(\KL(q_1\|q_2)+\KL(q_2\|q_1))\le 2\|r-s\|_\infty$.
\end{abstract}

\section{Introduction}

\subsection{The objective}

Alignment of a generative model by reinforcement learning from preference data optimizes, for each prompt, a distribution over responses. Fixing the prompt and writing $\Omega$ for the finite set of admissible responses, the standard objective with a pretraining mix-in reads
\[
J_\gamma(q) \;=\; \sum_{y\in\Omega} q(y)r(y) \;-\; \beta \sum_{y} q(y)\log\frac{q(y)}{p(y)} \;+\; \gamma \sum_{y} d(y)\log q(y),
\]
with $r:\Omega\to\R$ the reward model, $p$ the strictly positive reference (supervised fine-tuned) policy, $\beta>0$ the KL temperature, $d$ the pretraining distribution, and $\gamma\ge0$ the mix-in coefficient. We write $\KL(q\|p)=\sum_y q(y)\log\frac{q(y)}{p(y)}$ and $H(d)=-\sum_y d(y)\log d(y)$.

\subsection{Conventions}

$\Omega$ is finite and nonempty. A function $q:\Omega\to\R$ is a \emph{distribution} if $q\ge0$ pointwise and $\sum_y q(y)=1$, and a \emph{positive distribution} if additionally $q>0$ pointwise. Reference and candidate policies are positive distributions throughout; $d$ is a distribution, occasionally assumed to satisfy $d\ge\delta>0$.

\section{The Gibbs core}

\begin{definition}[Partition function, free energy, Gibbs policy]
For $\beta>0$, a reward $r$, and a positive distribution $p$, put
\[
Z_\beta(r,p)=\sum_y p(y)e^{r(y)/\beta},\qquad
F_\beta(r,p)=\beta\log Z_\beta(r,p),\qquad
\pi_r(y)=\frac{p(y)e^{r(y)/\beta}}{Z_\beta(r,p)} .
\]
We call $F_\beta(r,p)$ (written $F(r)$) the \emph{alignment value} and $\pi_r$ the \emph{Gibbs policy}.
\end{definition}

\begin{definition}[Objectives and implicit reward]
$\mathcal{J}(q)=\sum_y q(y)r(y)-\beta\KL(q\|p)$ and $J_\gamma(q)=\mathcal{J}(q)+\gamma\sum_y d(y)\log q(y)$. The \emph{implicit reward} of a positive distribution $q$ relative to $p$ is $\rho_{p,q}(y)=\beta\log\frac{q(y)}{p(y)}$.
\end{definition}

\begin{proposition}[Variational principle]\label{prop:var}
For every distribution $q$,
\[
\mathcal{J}(q)=F(r)-\beta\,\KL(q\,\|\,\pi_r).
\]
Hence $\mathcal{J}(q)\le F(r)$, with equality if and only if $q=\pi_r$.
\end{proposition}

\begin{proof}[Proof sketch]
Expand $\KL(q\|\pi_r)=\sum_y q(y)\log\frac{q(y)}{p(y)}-\frac1\beta\sum_y q(y)r(y)+\log Z$, using $\sum_y q(y)=1$ to absorb $\log Z$; multiply by $\beta$ and rearrange. The equality case is that of nonnegativity of the KL divergence.
\end{proof}

\begin{lemma}[Gauge, composition, inversion]\label{lem:core}
For a constant $c$: $F(r+c)=F(r)+c$ and $\pi_{r+c}=\pi_r$. Tilting composes additively: tilting $p$ by $r_1$ and then by $r_2$ gives the tilt by $r_1+r_2$. Finally, tilting $p$ by $\rho_{p,q}$ returns $q$.
\end{lemma}

\begin{proof}[Proof sketch]
The first two are direct computations with the exponential. For the third, $p(y)e^{\rho_{p,q}(y)/\beta}=q(y)$, so the partition function equals $\sum_y q(y)=1$.
\end{proof}

\section{The alignment torsor}

\begin{theorem}[Identifiability]\label{thm:ident}
For $\beta>0$ and positive $p$, $\pi_{r_1}=\pi_{r_2}$ if and only if $r_1-r_2$ is constant.
\end{theorem}

\begin{proof}[Proof sketch]
Sufficiency is Lemma~\ref{lem:core}. For necessity, equality of the tilts gives $e^{(r_1(y)-r_2(y))/\beta}=Z_1/Z_2$ for all $y$; take logarithms.
\end{proof}

\begin{theorem}[Alignment Torsor Theorem]\label{thm:torsor}
Let $\mathcal{R}=\R^\Omega$, let $\mathcal{C}\le\mathcal{R}$ be the subgroup of constant rewards, and let $\mathcal{P}$ be the set of positive distributions on $\Omega$. Exponential tilting defines an action of $\mathcal{R}$ on $\mathcal{P}$ that is transitive with stabilizer exactly $\mathcal{C}$ at every point. Hence $\mathcal{R}/\mathcal{C}$ acts simply transitively, and for each fixed $p$ the map $[r]\mapsto\pi_r$ is a bijection $\mathcal{R}/\mathcal{C}\to\mathcal{P}$ with inverse $q\mapsto[\rho_{p,q}]$.
\end{theorem}

\begin{proof}[Proof sketch]
Action axioms and transitivity are Lemma~\ref{lem:core}; freeness modulo constants is Theorem~\ref{thm:ident}.
\end{proof}

Fix the gauge by centering: $\mathcal{R}_0=\{r:\sum_y r(y)=0\}$, and let
\[
\hat\rho_{p,q}(y)=\rho_{p,q}(y)-\frac{1}{|\Omega|}\sum_z \rho_{p,q}(z)\in\mathcal{R}_0 .
\]

\begin{theorem}[Topological torsor]\label{thm:topo}
For $\beta>0$ and positive $p$, the map $\mathcal{R}_0\to\mathcal{P}$, $r\mapsto\pi_r$, is a homeomorphism with inverse $q\mapsto\hat\rho_{p,q}$, and it intertwines tilting with translation of rewards.
\end{theorem}

\begin{proof}[Proof sketch]
Bijectivity follows from Theorems~\ref{thm:ident} and Lemma~\ref{lem:core} together with the fact that each gauge class meets $\mathcal{R}_0$ once. Forward continuity: $Z_\beta(\cdot,p)$ is continuous and strictly positive. Backward continuity: on $\mathcal{P}$ every coordinate is locally bounded away from $0$, so $\log(q/p)$ is continuous; subtracting the mean preserves continuity.
\end{proof}

\begin{corollary}[Stability and collapse]
The aligned policy depends continuously on the reward, and the extracted reward depends continuously on the policy, but only on the interior of the simplex: as $q(y)\downarrow 0$ the implicit reward diverges to $-\infty$. Policy collapse is exactly the degeneration of this coordinate chart.
\end{corollary}

\section{Legendre duality between value and penalty}

\begin{theorem}[Gibbs--Bogoliubov--Feynman with exact remainder]\label{thm:gbf}
For rewards $r,s$, positive $p$, and $\beta>0$,
\[
F(s)\;\ge\;F(r)+\E_{\pi_r}[\,s-r\,],
\qquad\text{and precisely}\qquad
F(s)-F(r)-\E_{\pi_r}[\,s-r\,]=\beta\,\KL(\pi_r\|\pi_s).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Apply Proposition~\ref{prop:var} with reward $s$ and test policy $\pi_r$, then with reward $r$ and the same test policy (where the KL term vanishes), and subtract.
\end{proof}

\begin{corollary}
$F$ is convex along segments and monotone in the reward; equality in Theorem~\ref{thm:gbf} holds iff $s-r$ is constant, so $F$ is strictly convex transverse to the gauge; and $F(r+c)=F(r)+c$.
\end{corollary}

\begin{theorem}[Primal attainment]\label{thm:primal}
For $\beta>0$ and positive $p$,
\[
F(r)=\max\Big\{\E_q[r]-\beta\KL(q\|p)\;:\;q\text{ a distribution}\Big\},
\]
attained (uniquely among positive $q$) at $q=\pi_r$.
\end{theorem}

\begin{theorem}[Fenchel--Young and its equality case]\label{thm:fy}
For every distribution $q$, $\E_q[r]\le F(r)+\beta\KL(q\|p)$, and equality holds if and only if $q=\pi_r$.
\end{theorem}

\begin{proof}[Proof sketch]
By Proposition~\ref{prop:var} the gap equals $\beta\KL(q\|\pi_r)$.
\end{proof}

\begin{theorem}[Dual attainment: the KL penalty is the convex conjugate of the value]\label{thm:dual}
For $\beta>0$ and positive distributions $p,q$,
\[
\beta\,\KL(q\|p)=\max\Big\{\E_q[r]-F(r)\;:\;r:\Omega\to\R\Big\},
\]
attained at the implicit reward $r=\rho_{p,q}=\beta\log(q/p)$.
\end{theorem}

\begin{proof}[Proof sketch]
$F(\rho_{p,q})=0$ because $p(y)e^{\rho_{p,q}(y)/\beta}=q(y)$ makes the partition function equal $1$; and $\E_q[\rho_{p,q}]=\beta\KL(q\|p)$. The upper bound is Theorem~\ref{thm:fy}.
\end{proof}

\begin{remark}
Theorems~\ref{thm:primal} and~\ref{thm:dual} exhibit $F$ and $\beta\KL(\cdot\|p)$ as a Legendre-conjugate pair for the pairing $\langle q,r\rangle=\E_q[r]$, with maximizers attained on both sides, so no subdifferential theory is needed. Rewards and policies are dual coordinates and the tilting torsor is the gradient correspondence between them; its graph is the equality set of Fenchel--Young.
\end{remark}

\section{Reward hacking: a sharp budget}

\begin{theorem}[Reward-hacking budget]\label{thm:lip}
If $|r(y)-s(y)|\le K$ for all $y$ then $|F(r)-F(s)|\le K$.
\end{theorem}

\begin{proof}[Proof sketch]
$s\le r+K$ pointwise, so monotonicity and the shift rule give $F(s)\le F(r)+K$; symmetrize.
\end{proof}

\begin{theorem}[Sharpness]\label{thm:sharp}
For every $K\ge0$ and every $\varepsilon>0$ there are a temperature $\beta>0$, a reference policy $p$ on a two-element response space, and rewards $r,s$ with $\sup_y|r(y)-s(y)|\le K$ and $|F(r)-F(s)|>K-\varepsilon$.
\end{theorem}

\begin{proof}[Proof sketch]
Take $\Omega=\{0,1\}$, $p\equiv 1/2$, $r\equiv0$ and $s$ the spike $s(1)=K$, $s(0)=0$. Then $F(r)=0$ and
$F(s)=\beta\log\frac{e^{K/\beta}+1}{2}\ge K-\beta\log2$. Choose $\beta=\varepsilon/2$ and use $\log2\le1$.
\end{proof}

\begin{corollary}
No constant $c<1$ satisfies $|F(r)-F(s)|\le c\sup_y|r-s|$ in general.
\end{corollary}

\begin{theorem}[Reference weighting fails]\label{thm:refweight}
For every constant $C$ there are $\beta>0$, a positive reference $p$ on a two-element response space, and rewards $r,s$ with
\[
C\Big(\sum_y p(y)(r(y)-s(y))^2\Big)^{1/2}\;<\;|F(r)-F(s)| .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Take $p(1)=\delta$, $p(0)=1-\delta$, $r\equiv0$, $s$ the unit spike. The weighted distance is $\sqrt\delta$, while $F(s)\ge 1+\beta\log\delta$. Choose $\beta=1/(2\log(1/\delta)+2)$ so that $F(s)\ge1/2$, then $\delta\le 1/(16(C^2+1))$ so that $C\sqrt\delta\le1/4$.
\end{proof}

\begin{remark}
Any norm dominating the sup-norm (for instance unweighted $\ell^2$) inherits Theorem~\ref{thm:lip}. It is precisely the \emph{reference-weighted} norms, which discount responses the base model rarely emits, that fail: exponential tilting amplifies the tail of $p$ without limit.
\end{remark}

\section{The pretraining mix-in}

\begin{theorem}[Strict midpoint concavity]\label{thm:concave}
Let $\beta>0$, $\gamma\ge0$, $d\ge0$, $p$ positive, and let $q_1\ne q_2$ be positive distributions. Then
$J_\gamma\big(\tfrac{q_1+q_2}{2}\big)>\tfrac12 J_\gamma(q_1)+\tfrac12 J_\gamma(q_2)$. Consequently $J_\gamma$ has at most one maximizer.
\end{theorem}

\begin{proof}[Proof sketch]
$J_\gamma$ is a sum of coordinatewise terms: an affine reward term, the strictly concave $t\mapsto -\beta t\log(t/p(y))$, and the concave $t\mapsto\gamma d(y)\log t$. Strictness at a coordinate where $q_1,q_2$ differ gives the strict inequality.
\end{proof}

\begin{theorem}[Existence and uniqueness]\label{thm:exist}
Let $\beta>0$, $\gamma>0$, $p$ positive and $d(y)\ge\delta>0$ for all $y$. Then $J_\gamma$ attains a maximum over positive distributions at a unique $q^*$.
\end{theorem}

\begin{proof}[Proof sketch]
If some coordinate satisfies $q(y_0)\le\varepsilon$ then $\gamma d(y_0)\log q(y_0)\le\gamma\delta\log\varepsilon\to-\infty$, while the other terms are bounded above; hence for suitable $\varepsilon>0$ the search may be restricted to the compact slice $\Delta_\varepsilon=\{q:\ q\ge\varepsilon,\ \sum_y q(y)=1\}$, on which $J_\gamma$ is continuous. Uniqueness is Theorem~\ref{thm:concave}.
\end{proof}

\begin{definition}[Coordinatewise score]
For a positive policy $q$, set
\[
S_q(y)=r(y)-\beta\Big(\log\frac{q(y)}{p(y)}+1\Big)+\gamma\,\frac{d(y)}{q(y)} .
\]
\end{definition}

\begin{theorem}[Exact characterization]\label{thm:stat}
Let $\beta>0$, $\gamma\ge0$, $d\ge0$, and $p,q$ positive distributions. Then $q$ maximizes $J_\gamma$ if and only if $S_q$ is constant on $\Omega$; and if $S_q$ is constant then $J_\gamma(q')<J_\gamma(q)$ for every positive $q'\ne q$.
\end{theorem}

\begin{proof}[Proof sketch]
\emph{Necessity}: for $y_1\ne y_2$ the mass-shifting family $q_\varepsilon=q+\varepsilon(\mathbf 1_{y_1}-\mathbf 1_{y_2})$ stays a positive distribution for small $|\varepsilon|$, and $\varepsilon\mapsto J_\gamma(q_\varepsilon)$ is differentiable at $0$ with derivative $S_q(y_1)-S_q(y_2)$; a local maximum forces this to vanish. \emph{Sufficiency}: coordinatewise concavity yields the tangent bound $\phi_y(t')\le\phi_y(q(y))+S_q(y)(t'-q(y))$, where $\phi_y$ is the $y$-th term of $J_\gamma$; the required elementary inequality is $\log t\le t-1$ with equality iff $t=1$. Summing over $y$ with $t'=q'(y)$ and using constancy makes the linear term telescope to $0$.
\end{proof}

\begin{theorem}[Self-consistent Gibbs form]\label{thm:fixedpoint}
Let $\beta>0$ and $p$ positive. A positive distribution $q$ maximizes $J_\gamma$ if and only if
\[
q(y)=\frac{p(y)\exp\!\big(\tfrac1\beta(r(y)+\gamma d(y)/q(y))\big)}{\sum_z p(z)\exp\!\big(\tfrac1\beta(r(z)+\gamma d(z)/q(z))\big)},
\qquad\text{i.e.}\qquad q=\pi_{\,r+\gamma d/q}.
\]
Under $\gamma>0$ and $d\ge\delta>0$ such a fixed point exists and is unique.
\end{theorem}

\begin{proof}[Proof sketch]
Constancy $S_q\equiv c$ rearranges to $q(y)=p(y)e^{\tilde r(y)/\beta}\kappa$ with $\tilde r=r+\gamma d/q$ and $\kappa=e^{-(\beta+c)/\beta}$ independent of $y$; summing to $1$ identifies $\kappa=1/Z_\beta(\tilde r,p)$. Conversely, if $q=\pi_{\tilde r}$ then substituting $\log\frac{q(y)}{p(y)}=\tilde r(y)/\beta-\log Z_\beta(\tilde r,p)$ into $S_q$ gives the constant $\beta\log Z_\beta(\tilde r,p)-\beta$; apply Theorem~\ref{thm:stat}. Existence and uniqueness are Theorem~\ref{thm:exist}.
\end{proof}

\begin{remark}
The mix-in acts exactly as a self-referential reward bonus $\gamma d(y)/q(y)$, large precisely on responses that the pretraining distribution likes and the current policy has suppressed.
\end{remark}

\begin{theorem}[Anti-starvation]\label{thm:floor}
Let $\beta>0$, $\gamma>0$, $p$ positive, $d$ a distribution, and $r(y)\le M$ for all $y$. If $q$ maximizes $J_\gamma$ then for every $y$ with $d(y)>0$,
\[
q(y)\;\ge\;\frac{\gamma\,d(y)}{\beta\log\frac{1}{p(y)}+M+\gamma-r(y)}\;>\;0 .
\]
\end{theorem}

\begin{proof}[Proof sketch]
Averaging $S_q\equiv c$ against $q$ gives $c=\E_q[r]-\beta\KL(q\|p)-\beta+\gamma$. Substituting into $S_q(y)=c$ and using $q(y)\le1$, $\E_q[r]\le M$ and $\KL(q\|p)\ge0$ yields $\gamma d(y)/q(y)\le\beta\log\frac1{p(y)}+M+\gamma-r(y)$.
\end{proof}

\section{Drift}

\begin{lemma}[KL form of the mix-in objective]\label{lem:klform}
For positive $q$ and a distribution $d$, with $\pi=\pi_r$,
\[
J_\gamma(q)=F(r)-\beta\KL(q\|\pi)-\gamma H(d)-\gamma\KL(d\|q).
\]
\end{lemma}

\begin{theorem}[Pythagorean inequality]\label{thm:pyth}
If $J_\gamma(\pi)\le J_\gamma(q)$ (in particular if $q$ is the optimum) then
\[
\beta\,\KL(q\|\pi)+\gamma\,\KL(d\|q)\;\le\;\gamma\,\KL(d\|\pi).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Apply Lemma~\ref{lem:klform} at $q$ and at $\pi$ (where $\KL(\pi\|\pi)=0$) and subtract.
\end{proof}

\begin{corollary}
$\KL(q\|\pi)\le(\gamma/\beta)\KL(d\|\pi)$. If $d=\pi$ then $q=\pi$: the mix-in has no effect. For any selection of optima, $\KL(q^*_\gamma\|\pi)\to0$ as $\gamma\to0^+$, so the mix-in objective degenerates continuously into plain KL-regularized alignment.
\end{corollary}

\section{Comparative statics and stability}

Write $T(q)=\sum_y d(y)\log q(y)$, so $J_\gamma=\mathcal{J}+\gamma T$.

\begin{theorem}[Monotone pretraining fit and monotone alignment tax]\label{thm:compstat}
Let $0\le\gamma_1<\gamma_2$ and let $q_i$ maximize $J_{\gamma_i}$. Then $T(q_1)\le T(q_2)$ and $\mathcal{J}(q_2)\le\mathcal{J}(q_1)$.
\end{theorem}

\begin{proof}[Proof sketch]
Adding the two optimality inequalities cancels the $\mathcal{J}$ terms and leaves $(\gamma_2-\gamma_1)T(q_1)\le(\gamma_2-\gamma_1)T(q_2)$. Feeding this back into $J_{\gamma_1}(q_2)\le J_{\gamma_1}(q_1)$ gives the second claim.
\end{proof}

\begin{theorem}[Value: decreasing and convex in $\gamma$]\label{thm:envelope}
If $\gamma_1\le\gamma_2$, $d\ge0$ and $q_1$ maximizes $J_{\gamma_1}$, then $J_{\gamma_2}(q)\le J_{\gamma_1}(q_1)$ for every positive distribution $q$. Moreover, for $\theta\in[0,1]$ and maximizers $q_i$ of $J_{\gamma_i}$, every positive $q_\theta$ satisfies
\[
J_{\theta\gamma_1+(1-\theta)\gamma_2}(q_\theta)\;\le\;\theta J_{\gamma_1}(q_1)+(1-\theta)J_{\gamma_2}(q_2),
\]
so the optimal value $V(\gamma)$ is convex.
\end{theorem}

\begin{proof}[Proof sketch]
$T(q)\le0$ for distributions, giving monotonicity. For convexity, $J_\gamma(q)$ is affine in $\gamma$ for fixed $q$; bound each piece by the corresponding optimum. A maximum of affine functions is convex.
\end{proof}

\begin{lemma}[Strong concavity at the optimum]\label{lem:strong}
If $q_1$ maximizes $J_\gamma$ for reward $r$, then $J_\gamma(q_2)+\beta\KL(q_2\|q_1)\le J_\gamma(q_1)$ for every positive distribution $q_2$.
\end{lemma}

\begin{theorem}[Two-sided KL stability and the immunity band]\label{thm:stab}
Let $q_1,q_2$ be the mix-in optima for rewards $r,s$ (same $\beta,\gamma,p,d$). Then
\[
\beta\big(\KL(q_1\|q_2)+\KL(q_2\|q_1)\big)\;\le\;\sum_y (q_1(y)-q_2(y))(r(y)-s(y)),
\]
and if $|r(y)-s(y)|\le K$ for all $y$ then the left side is at most $2K$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply Lemma~\ref{lem:strong} twice and add; the mix-in and KL-to-$p$ parts cancel because the objectives differ only through the linear reward pairing. Then bound $|q_1(y)-q_2(y)|\,K\le(q_1(y)+q_2(y))K$ and sum.
\end{proof}

\section{Algorithms}

\begin{enumerate}
\item[\textbf{(A)}] \emph{Exact aligned policy} ($\gamma=0$): compute $\pi_r\propto p\,e^{r/\beta}$ by a stable softmax on $\log p+r/\beta$, and $F(r)=\beta\,\mathrm{logsumexp}(\log p+r/\beta)$. Cost $O(|\Omega|)$.
\item[\textbf{(B)}] \emph{Mix-in optimum by self-consistent tilting}: iterate $q_{k+1}=(1-\lambda)q_k+\lambda\,\pi_{r+\gamma d/q_k}$ from $q_0=\pi_r$ with damping $\lambda\in(0,1]$. By Theorem~\ref{thm:fixedpoint} the fixed points are exactly the optima, and by Theorem~\ref{thm:concave} the optimum is unique, so any convergent run lands on the answer. Certify a posteriori by the score spread $\max_y S_q(y)-\min_y S_q(y)$ (Theorem~\ref{thm:stat}).
\item[\textbf{(B$'$)}] \emph{Dual bisection} (globally convergent): the iteration in (B) is not a contraction in general and can oscillate. Fix a trial value $c$ for the common score; for each $y$ the equation $r(y)-\beta(\log(t/p(y))+1)+\gamma d(y)/t=c$ has a unique root $t_y(c)>0$ (the left side is strictly decreasing in $t$), and $t_y(c)$ is strictly decreasing in $c$. Hence the mass $\mathrm{M}(c)=\sum_y t_y(c)$ is strictly decreasing from $+\infty$ to $0$, and bisection on $c$ locates the unique $c^*$ with $\mathrm{M}(c^*)=1$; then $q^*=(t_y(c^*))_y$. Cost $O(|\Omega|\log(1/\epsilon)^2)$ with a guaranteed bracket.
\item[\textbf{(C)}] \emph{Certified projected ascent}: maximize over the compact slice $\Delta_\varepsilon$ of Theorem~\ref{thm:exist} and certify by the same score test; the barrier estimate supplies a safe $\varepsilon$.
\end{enumerate}

For $\gamma=0$ the Fenchel--Young gap $F(r)+\beta\KL(q\|p)-\E_q[r]$ is an exact suboptimality measure (Theorem~\ref{thm:fy}), and Theorem~\ref{thm:pyth} gives an a priori trust region for the mix-in answer.

\section{Discussion and future work}

All results are for a fixed prompt and a finite response space with strictly positive reference policy; finiteness enters through compactness and the coordinatewise perturbation argument, and positivity of $p$ is essential since the torsor and duality statements live on the interior of the simplex. The mix-in optimum is characterized but not solved in closed form: Theorem~\ref{thm:fixedpoint} gives a fixed-point equation, and a contraction modulus for the iteration $q\mapsto\pi_{r+\gamma d/q}$ in terms of $\beta,\gamma,\delta$ would upgrade algorithm (B) to a certified linear-rate method.

\begin{conjecture}[Sharpness of the drift bound]
For the mix-in optimum, $\KL(q^*_\gamma\|\pi)=\frac{\gamma^2}{2\beta^2}\Var_\pi(d/\pi)+O(\gamma^3)$ as $\gamma\to0^+$, so the linear bound $\KL(q^*_\gamma\|\pi)\le(\gamma/\beta)\KL(d\|\pi)$ is never tight for small $\gamma$, whereas the Pythagorean form approaches equality as $\gamma\to\infty$, where $q^*_\gamma\to d$. Heuristically the two KL terms are the legs of an information-geometric right triangle with fixed hypotenuse, and the deficit is the curvature of the exponential family joining $\pi$ to $d$.
\end{conjecture}

\begin{conjecture}[Curvature of the mix-in path]
The curve $\gamma\mapsto q^*_\gamma$ from $\pi_r$ to $d$ is not a geodesic of the exponential family through its endpoints, except in the degenerate case $d=\pi_r$.
\end{conjecture}

\begin{remark}
A caution recorded from the analysis: it is \emph{not} true that no $\ell^2$ bound on reward hacking can hold, since the unweighted $\ell^2$ norm dominates the sup-norm and Theorem~\ref{thm:lip} applies. The correct negative statement is the reference-weighted failure of Theorem~\ref{thm:refweight}.
\end{remark}

Further directions include sharpening the constant $2/\beta$ of Theorem~\ref{thm:stab} using local strong concavity (which should show that the mix-in improves robustness rather than merely preserving it), extending the torsor to a bundle over a prompt distribution and asking whether cross-prompt consistency reduces the gauge group, and determining when the torsor structure descends to autoregressive factorizations of sequence-level policies.

\section{Conclusion}

The alignment objective with pretraining mix-in decomposes into three geometrically distinct pieces. The reward contributes a linear functional. The KL penalty is the exact convex conjugate of the achievable alignment value, making rewards-modulo-constants and strictly positive policies Legendre-dual coordinates related by a simply transitive tilting action that is a homeomorphism on the interior of the simplex. The pretraining mix-in is an interior barrier acting as a self-referential reward bonus $\gamma d/q$; it replaces the closed-form Gibbs solution by an equivalent fixed-point equation and buys a hard, reward-independent probability floor at a monotone and convex price in alignment value. A sup-norm-$K$ corruption of the reward model moves the value by at most $K$ --- sharply --- and the policy by at most $2K/\beta$ in symmetrized information distance, and no reference-weighted diagnostic can detect it.

